+              onChange={(event) => setJobDescription(event.target.value)}
+            />
+          </div>
+          <button
+            type="submit"
+            className="button button--ghost"
+            disabled={creatingJob || !jobName.trim()}
+          >
+            {creatingJob ? "Adding…" : "Add job"}
+          </button>
+        </form>
+      </details>
+    </div>
+  );
+}

