+          icon: <BoltIcon size={15} />,
+          run: () => onSubmit(GUIDELINES_PROMPT),
+          conversational: true,
+        },
+    jobs > 0
+      ? {
+          id: "capture",
+          label: "Capture an outcome",
+          icon: <CaptureIcon size={15} />,
+          run: () =>
+            llmHealth.healthy === false
+              ? openPanel("capture")
