+
+type FilterType = "all" | "unread" | "outcome" | "signals";
+
+function formatRelativeTime(isoString: string): string {
+  try {
+    const date = new Date(isoString);
+    const now = new Date();
+    const diffMs = now.getTime() - date.getTime();
+    const diffMins = Math.floor(diffMs / (1000 * 60));
+    const diffHours = Math.floor(diffMins / 60);
+    const diffDays = Math.floor(diffHours / 24);
+
+    if (diffMins < 1) return "Just now";
+    if (diffMins < 60) return `${diffMins}m ago`;
+    if (diffHours < 24) return `${diffHours}h ago`;
+    return `${diffDays}d ago`;
+  } catch {
+    return "Recently";
+  }
+}
+
+function getCategoryIcon(category: NotificationCategory) {
+  switch (category) {
+    case "outcome":
+      return <CompassIcon size={16} />;
+    case "simulation":
+      return <BoltIcon size={16} />;
+    case "evidence":
+      return <SignalIcon size={16} />;
+    case "job":
+      return <RouteIcon size={16} />;
+    case "insight":
+    default:
+      return <SparkIcon size={16} />;
+  }
+}
+
+function getCategoryBadgeClass(category: NotificationCategory): string {
+  switch (category) {
+    case "outcome":
+      return "badge--blue";
+    case "simulation":
+      return "badge--amber";
+    case "evidence":
+      return "badge--green";
+    case "job":
+    case "insight":
+    default:
+      return "badge--blue";
+  }
+}
