+
+      {/* Filter Chips */}
+      <div className="chips" role="tablist" aria-label="Filter notifications">
+        <button
+          type="button"
+          role="tab"
+          aria-selected={activeFilter === "all"}
+          className={`chip${activeFilter === "all" ? " is-on" : ""}`}
+          onClick={() => setActiveFilter("all")}
