- * Microphone capture for the copilot's voice input.
- *
- * The browser gives us two ways to hear the user, and they fail in different
- * places. `getUserMedia` + `MediaRecorder` needs a secure context and a
- * granted microphone permission; the browser's own `SpeechRecognition` needs
- * a vendor implementation. This module owns the first path and the failure
- * vocabulary both paths share.
- */
-
-/** Why a recording could not be made. */
-export type RecorderFailureReason =
-  | "unsupported"
-  | "insecure"
-  | "denied"
-  | "no-device"
-  | "no-recorder";
-
-/** The user-facing message for each failure. Specific beats vague. */
-const FAILURE_MESSAGES: Record<RecorderFailureReason, string> = {
-  unsupported: "This browser cannot record audio. Use the desktop app or a Chromium browser.",
-  insecure: "Recording needs a secure connection. Open the studio over https or on localhost.",
-  denied: "Microphone access was denied. Allow it in your browser's site settings.",
-  "no-device": "No microphone was found.",
-  "no-recorder": "This browser cannot record audio.",
-};
-
-/** The MIME types we can record, best first. */
-const PREFERRED_MIME_TYPES = [
-  "audio/webm;codecs=opus",
-  "audio/webm",
-  "audio/mp4",
-];
-
-/** Thrown when a recording cannot be started or completed. */
-export class RecorderError extends Error {
-  readonly reason: RecorderFailureReason;
-
-  constructor(reason: RecorderFailureReason) {
-    super(FAILURE_MESSAGES[reason]);
-    this.name = "RecorderError";
-    this.reason = reason;
-  }
-}
-
-/** The user-facing message for a failure reason. */
-export function describeRecorderFailure(reason: RecorderFailureReason): string {
-  return FAILURE_MESSAGES[reason];
-}
-
-/** True when this browser exposes the APIs needed to record audio. */
-export function recorderSupported(): boolean {
-  return (
-    typeof navigator !== "undefined" &&
-    typeof navigator.mediaDevices?.getUserMedia === "function" &&
-    typeof window !== "undefined" &&
-    typeof window.MediaRecorder === "function"
