+        {outcomeId ? (
+          <div className="ui-field">
+            <dt>Serves</dt>
+            <dd>{outcomeId}</dd>
+          </div>
+        ) : null}
+        <div className="ui-field">
+          <dt>Why</dt>
+          <dd>
+            <Markdown source={rationale} />
+          </dd>
+        </div>
+      </dl>
+
+      <ActionRow actions={readActions(node.props)} />
+    </article>
+  );
+}

